var out = []
var stack = [tree.root.get_node("/root/PadHintBar")]
while stack.size() > 0:
	var n = stack.pop_front()
	if n is Label:
		out.append(n.text)
	for c in n.get_children():
		stack.append(c)
return "Continue" in out and not ("Cycle Units" in out)

for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		t.queue_free()
ToastManager.active_toasts.clear()
TutorialManager._last_block_toast_ms = 0
return ToastManager.active_toasts.size()

for c in tree.root.get_children():
	if c is Window and c != tree.root and c.visible:
		return str(c.name)
return "none"

var found = false
for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.get_children():
		if c is Label and "Continue" in c.text:
			found = true
return found
